$f = @{}
$f["acerca.html"]    = ""
$f["glosario.html"]  = ""
$f["canciones.html"] = ""
$f["cancion.html"]   = ""

foreach ($k in $f.Keys) {
  $b = [System.Convert]::FromBase64String($f[$k])
  [System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $k), $b)
}

git add -A
git commit -m "fix: restaurar 4 HTML (acerca/glosario/canciones/cancion) v0.2.5"
git push origin main
git log -1 --oneline
